insert into public.languages(code,name) values('en','English'),('zu','isiZulu'),('xh','isiXhosa'),('nso','Sepedi'),('tn','Setswana'),('af','Afrikaans'),('st','Sesotho'),('ts','itsonga'),('ss','siSwati'),('ve','Tshivenda'),('nd','isiNdebele') on conflict(code) do nothing;
insert into public.cultures(name,description) values('Zulu','Zulu oral storytelling traditions'),('Xhosa','Xhosa oral storytelling traditions'),('Sotho','Southern African Sotho storytelling traditions'),('Tswana','Setswana oral traditions'),('Tsonga','Tsonga oral traditions'),('Venda','Tshivenda oral traditions') on conflict(name) do nothing;
do $$declare lang uuid; cult uuid; begin select id into lang from public.languages where code='zu';select id into cult from public.cultures where name='Zulu';insert into public.stories(slug,title,summary,language_id,culture_id,age_min,age_max,themes,moral_lesson,access_level,status) values('the-hungry-crocodile','The Hungry Crocodile','A pilot story record demonstrating DFC metadata, language and wisdom fields.',lang,cult,5,10,array['wisdom','community'],'Wisdom grows when it is shared with the community.','public','draft') on conflict(slug) do nothing;end $$;
do $$begin insert into public.fire_circles(title,description,starts_at,status,capacity) values('Saturday Family Fire','A gentle pilot circle for families to listen together.',now()+interval '3 days','scheduled',40);exception when unique_violation then null;end $$;
